for nm in ["k_copy","k_empty_w","k_empty_nc","k_empty"]:
    k=bp.Kernel(cub,nm)
    try: print(nm, bp.harness_time(lambda g,o,k=k: k((16,),(256,),g,o,n), [g],[o]))
    except Exception as e: print(nm, "ERR", str(e)[:200])

